-- | The differential check against the reference implementation.
--
-- @differential/net_definition_corpus.json@ is generated by
-- @differential/net_definition_corpus.py@ from the pinned Python reference:
-- each case is one payload handed to @parse_net_definition@ or
-- @parse_net_document@ together with the reference's verdict (the canonical
-- serialization, or its SHA-256, plus the definition identity for documents;
-- or the exact refusal message). This spec rebuilds every payload and asserts
-- the Haskell port reaches the same verdict byte for byte.
--
-- Payloads are stored compactly: literal text or base64, a repetition
-- (deep nesting, huge integers), a structural mutation of a named base value,
-- or byte edits of a named base spelling.
module Petrus.Impetus.NetDefinitionCorpusSpec (spec, findPackageFile) where

import Control.Monad (filterM, forM_)
import Crypto.Hash.SHA256 qualified as SHA256
import Data.Bits (shiftL, shiftR, (.&.), (.|.))
import Data.ByteString (ByteString)
import Data.ByteString qualified as BS
import Data.Char (ord)
import Data.Text (Text)
import Data.Text qualified as T
import Data.Text.Encoding qualified as TE
import Data.Word (Word8)
import Numeric (showHex)
import Petrus.Impetus.NetDefinition
import Petrus.Impetus.NetDocument
import Petrus.Json
import System.Directory (doesPathExist)
import Test.Hspec

-- | The first existing candidate, relative to the package directory (where
-- @cabal test@ runs) or to the repository root.
findPackageFile :: [FilePath] -> IO FilePath
findPackageFile candidates =
  filterM doesPathExist candidates >>= \case
    found : _ -> pure found
    [] -> fail ("none of these paths exist: " <> show candidates)

data Verdict
  = Canonical Text (Maybe Text)
  | CanonicalDigest Text (Maybe Text)
  | Refused Text
  deriving stock (Eq, Show)

data Case = Case {name :: Text, kind :: Text, payload :: ByteString, verdict :: Verdict}

spec :: Spec
spec = describe "Petrus.Impetus.NetDefinition differential corpus" $ do
  path <- runIO (findPackageFile ["differential/net_definition_corpus.json", "packages/petrus-impetus/differential/net_definition_corpus.json"])
  raw <- runIO (BS.readFile path)
  cases <- runIO (either fail pure (loadCorpus raw))
  it "covers a substantial corpus" (length cases `shouldSatisfy` (> 1000))
  forM_ cases $ \c ->
    it (T.unpack (c.kind <> ": " <> c.name)) (haskellVerdict c `shouldBe` c.verdict)

haskellVerdict :: Case -> Verdict
haskellVerdict c = case c.kind of
  "definition" -> case parseNetDefinition c.payload >>= serializeNetDefinition of
    Left err -> Refused err
    Right bytes -> shape (TE.decodeUtf8 bytes) Nothing
  _ -> case parseNetDocument c.payload of
    Left err -> Refused err
    Right document -> case (,) <$> serializeNetDocument document <*> definitionIdentity document of
      Left err -> Refused ("unexpected: " <> err)
      Right (bytes, identity) -> shape (TE.decodeUtf8 bytes) (Just identity)
  where
    shape spelled identity = case c.verdict of
      CanonicalDigest _ _ -> CanonicalDigest (sha256Hex (TE.encodeUtf8 spelled)) identity
      _ -> Canonical spelled identity

sha256Hex :: ByteString -> Text
sha256Hex = T.pack . concatMap byte . BS.unpack . SHA256.hash
  where
    byte w = let h = showHex w "" in if length h == 1 then '0' : h else h

-- ---------------------------------------------------------------------------
-- Loading

loadCorpus :: ByteString -> Either String [Case]
loadCorpus raw = do
  corpus <- parseJson pythonLoads raw
  bases <- case lookupMember "bases" corpus of
    Just (Object members) -> traverse (traverse text) members
    _ -> Left "corpus has no bases"
  cases <- case lookupMember "cases" corpus of
    Just (Array items) -> pure items
    _ -> Left "corpus has no cases"
  traverse (loadCase bases) cases

loadCase :: [(Text, Text)] -> Json -> Either String Case
loadCase bases value = do
  name <- member "name" >>= text
  kind <- member "kind" >>= text
  payload <- rebuild bases value
  identity <- maybe (pure Nothing) (fmap Just . text) (lookupMember "identity" value)
  verdict <- case (lookupMember "error" value, lookupMember "canonical" value, lookupMember "canonical_sha256" value) of
    (Just err, _, _) -> Refused <$> text err
    (_, Just canonical, _) -> (`Canonical` identity) <$> text canonical
    (_, _, Just digest) -> (`CanonicalDigest` identity) <$> text digest
    _ -> Left ("case has no verdict: " <> T.unpack name)
  pure Case {name, kind, payload, verdict}
  where
    member key = maybe (Left ("case lacks " <> T.unpack key)) Right (lookupMember key value)

text :: Json -> Either String Text
text = \case
  String t -> Right t
  other -> Left ("expected a string, got " <> show other)

integer :: Json -> Either String Int
integer = \case
  Int i -> Right (fromInteger i)
  other -> Left ("expected an integer, got " <> show other)

rebuild :: [(Text, Text)] -> Json -> Either String ByteString
rebuild bases value
  | Just (String t) <- lookupMember "text" value = Right (TE.encodeUtf8 t)
  | Just (String b) <- lookupMember "base64" value = Right (decodeBase64 b)
  | Just r <- lookupMember "repeat" value = do
      let part key = maybe (Left "repeat lacks a part") text (lookupMember key r)
      prefix <- part "prefix"
      unit <- part "unit"
      middle <- part "middle"
      closing <- part "closing"
      suffix <- part "suffix"
      n <- maybe (Left "repeat lacks n") integer (lookupMember "n" r)
      Right (TE.encodeUtf8 (prefix <> T.replicate n unit <> middle <> T.replicate n closing <> suffix))
  | Just m <- lookupMember "mutation" value = do
      base <- baseBytes m >>= parseJson pythonLoads
      op <- maybe (Left "mutation lacks op") text (lookupMember "op" m)
      steps <- case lookupMember "path" m of
        Just (Array items) -> Right items
        _ -> Left "mutation lacks path"
      mutated <- mutate op steps (lookupMember "value" m) base
      either (Left . show) Right (dumps compact {allowNan = True} mutated)
  | Just f <- lookupMember "fuzz" value = do
      base <- baseBytes f
      edits <- case lookupMember "edits" f of
        Just (Array items) -> traverse edit items
        _ -> Left "fuzz lacks edits"
      Right (foldl (\bytes apply -> apply bytes) base edits)
  | otherwise = Left "case has no payload"
  where
    baseBytes spelling = do
      name <- maybe (Left "spelling lacks base") text (lookupMember "base" spelling)
      maybe (Left ("unknown base " <> T.unpack name)) (Right . TE.encodeUtf8) (lookup name bases)
    edit = \case
      Array [Int position, String op, Int byte] ->
        Right (applyEdit (fromInteger position) op (fromInteger byte))
      other -> Left ("malformed edit " <> show other)

applyEdit :: Int -> Text -> Word8 -> ByteString -> ByteString
applyEdit position op byte bytes =
  let (front, back) = BS.splitAt position bytes
   in case op of
        "insert" -> front <> BS.singleton byte <> back
        "delete" -> front <> BS.drop 1 back
        _ -> front <> BS.singleton byte <> BS.drop 1 back

-- | The generator's mutation operations on a decoded base value.
mutate :: Text -> [Json] -> Maybe Json -> Json -> Either String Json
mutate op steps replacement = go steps
  where
    go [] current = case op of
      "replace" -> maybe (Left "replace lacks value") Right replacement
      "extra" -> case current of
        Object members -> Right (Object (setMember "extra" extra members))
        _ -> Left "extra on a non-object"
      "reverse" -> list (Right . reverse) current
      "duplicate_first" -> list (\case x : xs -> Right (x : x : xs); [] -> Left "empty list") current
      "drop_first" -> list (Right . drop 1) current
      "empty" -> Right (Array [])
      _ -> Left ("unknown op " <> T.unpack op)
    go [String key] (Object members) | op == "delete" = Right (Object (filter ((/= key) . fst) members))
    go (String key : rest) (Object members) = case lookup key members of
      Just child -> (\new -> Object (setMember key new members)) <$> go rest child
      Nothing -> Left ("no member " <> T.unpack key)
    go (Int index : rest) (Array items)
      | (front, child : back) <- splitAt (fromInteger index) items = (\new -> Array (front <> (new : back))) <$> go rest child
    go _ _ = Left "mutation path does not fit the base"
    list f = \case
      Array items -> Array <$> f items
      _ -> Left "list operation on a non-list"
    extra = Array [Int 1, Object [("x", Null)]]

setMember :: Text -> Json -> [(Text, Json)] -> [(Text, Json)]
setMember key new members
  | any ((== key) . fst) members = [(k, if k == key then new else v) | (k, v) <- members]
  | otherwise = members <> [(key, new)]

decodeBase64 :: Text -> ByteString
decodeBase64 = BS.pack . go . map sextet . filter (/= '=') . T.unpack
  where
    sextet ch
      | ch >= 'A' && ch <= 'Z' = ord ch - ord 'A'
      | ch >= 'a' && ch <= 'z' = ord ch - ord 'a' + 26
      | ch >= '0' && ch <= '9' = ord ch - ord '0' + 52
      | ch == '+' = 62
      | otherwise = 63
    go (a : b : c : d : rest) = triple a b c d 3 <> go rest
    go [a, b, c] = triple a b c 0 2
    go [a, b] = triple a b 0 0 1
    go _ = []
    triple a b c d count =
      let n = (a `shiftL` 18) .|. (b `shiftL` 12) .|. (c `shiftL` 6) .|. d
       in take count [fromIntegral ((n `shiftR` 16) .&. 255), fromIntegral ((n `shiftR` 8) .&. 255), fromIntegral (n .&. 255)]
